async () => {
  const url = 'https://data.stats.gov.cn/easyquery.htm?m=QueryData&dbcode=fsnd&rowcode=reg&colcode=sj&wds=[]&dfwds=[{"wdcode":"zb","valuecode":"A020101"}]&k1=' + new Date().getTime();
  const r = await fetch(url, {credentials: 'include'});
  const t = await r.text();
  return {status: r.status, len: t.length, head: t.slice(0, 800)};
}

async () => {
  const urls = [
    'https://data.stats.gov.cn/dg/website/publicrelease/web/external/queryPbLibCatalogTree?code=3',
    'https://data.stats.gov.cn/dg/website/publicrelease/web/external/queryPbLibCatalogList?code=15',
    'https://data.stats.gov.cn/dg/website/publicrelease/web/external/queryPbLibCatalogList?code=16'
  ];
  const out = [];
  for (const u of urls) {
    try {
      const r = await fetch(u);
      const t = await r.text();
      out.push({url: u, status: r.status, len: t.length, body: t.slice(0, 3000)});
    } catch(e) { out.push({url: u, error: String(e)}); }
  }
  return out;
}

