args.function:
() => {
  const out = [];
  const els = document.querySelectorAll('a, li, [class*="menu"], [class*="sub"], [class*="drop"]');
  for (const el of els) {
    const t = (el.textContent || '').trim().replace(/\s+/g, ' ');
    if (t && (t.includes('地区') || t.includes('分省') || t.includes('年度数据') || t.includes('月度数据') || t.includes('季度数据') || t.includes('分地区'))) {
      const href = el.getAttribute && el.getAttribute('href');
      out.push({tag: el.tagName, cls: (el.className||'').toString().slice(0,60), text: t.slice(0,40), href: href});
    }
  }
  // dedupe
  const seen = new Set();
  return out.filter(o => { const k = JSON.stringify(o); if (seen.has(k)) return false; seen.add(k); return true; }).slice(0, 80);
}

