async () => {
  const r = await fetch('https://data.stats.gov.cn/dg/website/publicrelease/web/external/new/queryIndexTreeAsync?pid=&code=6');
  const j = await r.json();
  const walk = (nodes, depth) => (nodes||[]).map(n => ({name: n.name, id: n._id, pid: n.treeinfo_pid, type: n.type, depth})).slice(0,200);
  return walk(j.data, 0);
}

