args.function:
async () => {
  const fetchInd = async (cid) => {
    const r = await fetch('https://data.stats.gov.cn/dg/website/publicrelease/web/external/new/queryIndicatorsByCid?cid=' + cid + '&dt=2021-2025&name=');
    const j = await r.json();
    return (j.data && j.data.list || []).map(x => ({name: x.i_showname || x._name, _id: x._id, du: x.du_name, ek: x.ek, dp_name: x.dp_name}));
  };
  const gdp = await fetchInd('6f8fbd415cbc40ffa7ecb7fd917f2598');
  const pop = await fetchInd('755d5f6efbcf41a6a411ad819aa93c17');
  return {gdp, pop};
}

