async (page) => {
  const fs = require('fs');
  const path = require('path');
  const BASE = 'https://data.stats.gov.cn/dg/website/publicrelease/web/external';

  // 1) 地区列表（31个省级单位，不含港澳台）
  const daJson = await page.evaluate(async (base) => {
    const r = await fetch(base + '/getDasByDaCatalogId?daCid=a10dceae75d245008bf4b9a0e6fe1d55');
    return await r.json();
  }, BASE);
  const provinces = (daJson.data || []).map(d => ({name: d.show_name, code: d.name_value}));

  // 2) 数据抓取函数
  const fetchData = async (cid, indicatorId, rootId) => {
    return await page.evaluate(async ({base, cid, indicatorId, rootId, provinces}) => {
      const body = {
        cid: cid,
        indicatorIds: [indicatorId],
        daCatalogId: '',
        das: provinces.map(p => ({text: p.name, value: p.code})),
        showType: '1',
        dts: ['2021YY-2025YY'],
        rootId: rootId
      };
      const r = await fetch(base + '/stream/esData', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify(body)
      });
      return await r.json();
    }, {base: BASE, cid, indicatorId, rootId, provinces});
  };

  const ROOT = 'c4d82af16c3d4f0cb4f09d4af7d5888e';
  const gdp = await fetchData('6f8fbd415cbc40ffa7ecb7fd917f2598', 'aff57de5ee994283974705914fbed246', ROOT);
  const pop = await fetchData('755d5f6efbcf41a6a411ad819aa93c17', '4810ad6e9ddc41fc804a66134afe587f', ROOT);

  // 3) 落盘
  const outDir = '/home/shared-user/研究生/QGIS-agent/Eino/autocarto_data/data/sessions/Test1-b9d4ef3a555f47f6/d9fa0ac6-daf9-400b-996f-c5142fc41b65/output/gdp_population_data';
  fs.mkdirSync(outDir, {recursive: true});
  fs.writeFileSync(path.join(outDir, 'nbs_province_gdp_raw.json'), JSON.stringify(gdp, null, 2), 'utf8');
  fs.writeFileSync(path.join(outDir, 'nbs_province_population_raw.json'), JSON.stringify(pop, null, 2), 'utf8');

  // 4) 解析为 map: code+year -> value
  const parse = (resp) => {
    const m = {};
    for (const yr of (resp.data || [])) {
      const y = yr.name.replace('年','');
      for (const v of (yr.values || [])) {
        m[v.da + '|' + y] = v.value;
      }
    }
    return m;
  };
  const gdpMap = parse(gdp);
  const popMap = parse(pop);

  // 5) 生成规范化 CSV
  const years = ['2021','2022','2023','2024','2025'];
  let csv = 'adcode,adcode6,province,year,gdp_yiyuan,population_wanren\n';
  for (const p of provinces) {
    const adcode6 = p.code.slice(0,6);
    for (const y of years) {
      const g = gdpMap[p.code + '|' + y] !== undefined ? gdpMap[p.code + '|' + y] : '';
      const pp = popMap[p.code + '|' + y] !== undefined ? popMap[p.code + '|' + y] : '';
      csv += `${p.code},${adcode6},${p.name},${y},${g},${pp}\n`;
    }
  }
  fs.writeFileSync(path.join(outDir, 'nbs_province_gdp_population.csv'), csv, 'utf8');

  // 6) 每年非空值数量统计（判断最新完整年度）
  const yearNonEmpty = (m) => {
    const r = {};
    for (const y of years) {
      let n = 0;
      for (const p of provinces) { const v = m[p.code + '|' + y]; if (v !== undefined && v !== '') n++; }
      r[y] = n;
    }
    return r;
  };

  return {
    outDir,
    provinceCount: provinces.length,
    provinceNames: provinces.map(p=>p.name),
    gdpNonEmptyByYear: yearNonEmpty(gdpMap),
    popNonEmptyByYear: yearNonEmpty(popMap),
    gdpSample2024: provinces.slice(0,5).map(p => ({p:p.name, v: gdpMap[p.code+'|2024']})),
    popSample2024: provinces.slice(0,5).map(p => ({p:p.name, v: popMap[p.code+'|2024']})),
    gdpSample2025: provinces.slice(0,5).map(p => ({p:p.name, v: gdpMap[p.code+'|2025']})),
    popSample2025: provinces.slice(0,5).map(p => ({p:p.name, v: popMap[p.code+'|2025']}))
  };
}

