    const r = await fetch(BASE+'/stream/esData',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
    return await r.json();
  };
  const gdp = await fetchData('6f8fbd415cbc40ffa7ecb7fd917f2598','aff57de5ee994283974705914fbed246');
  const pop = await fetchData('755d5f6efbcf41a6a411ad819aa93c17','4810ad6e9ddc41fc804a66134afe587f');
  const parse=(r)=>{const m={};for(const y of r.data||[]){const yy=y.name.replace('年','');for(const v of y.values||[])m[v.da+'|'+yy]=v.value;}return m;};
  const g=parse(gdp), p=parse(pop);
  const years=['2021','2022','2023','2024','2025'];
  const ne=(m)=>{const o={};for(const y of years){let n=0;for(const pr of provinces){const v=m[pr.code+'|'+y];if(v!==undefined&&v!=='')n++;}o[y]=n;}return o;};
  return {
    provinceCount: provinces.length,
    gdpYears: (gdp.data||[]).map(y=>y.name),
    popYears: (pop.data||[]).map(y=>y.name),
    gdpNonEmpty: ne(g),
    popNonEmpty: ne(p),
